CREATE SCHEMA IF NOT EXISTS performance;
CREATE TABLE performance.services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,owner_team text NOT NULL,criticality text NOT NULL CHECK(criticality IN('tier1','tier2','tier3')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,service_key));
CREATE TABLE performance.budgets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,operation_key text NOT NULL,p50_ms integer NOT NULL CHECK(p50_ms>0),p95_ms integer NOT NULL CHECK(p95_ms>=p50_ms),p99_ms integer NOT NULL CHECK(p99_ms>=p95_ms),error_rate_bps integer NOT NULL CHECK(error_rate_bps BETWEEN 0 AND 10000),min_rps integer NOT NULL DEFAULT 1,web_vitals jsonb NOT NULL DEFAULT '{}'::jsonb,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,service_key,operation_key,active));
CREATE TABLE performance.load_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,name text NOT NULL,scenario text NOT NULL,environment text NOT NULL CHECK(environment IN('development','staging','production')),virtual_users integer NOT NULL CHECK(virtual_users BETWEEN 1 AND 20000),duration_seconds integer NOT NULL CHECK(duration_seconds BETWEEN 30 AND 86400),traffic_model jsonb NOT NULL,destructive boolean NOT NULL DEFAULT false,requires_approval boolean NOT NULL DEFAULT true,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,name));
CREATE TABLE performance.load_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,profile_id uuid NOT NULL REFERENCES performance.load_profiles(id),scenario text NOT NULL,environment text NOT NULL,state text NOT NULL CHECK(state IN('queued','running','passed','failed','cancelled')),virtual_users integer NOT NULL,duration_seconds integer NOT NULL,requests bigint NOT NULL DEFAULT 0,failures bigint NOT NULL DEFAULT 0,error_rate_bps integer NOT NULL DEFAULT 0,p50_ms integer,p95_ms integer,p99_ms integer,requested_by uuid NOT NULL,approved_by uuid,started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX performance_load_runs_queue_idx ON performance.load_runs(tenant_id,state,created_at DESC);
CREATE TABLE performance.budget_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,run_id uuid NOT NULL REFERENCES performance.load_runs(id),budget_id uuid NOT NULL REFERENCES performance.budgets(id),passed boolean NOT NULL,observed jsonb NOT NULL,reasons text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,run_id,budget_id));
CREATE TABLE performance.capacity_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,observed_rps integer NOT NULL,peak_rps integer NOT NULL,utilization_bps integer NOT NULL CHECK(utilization_bps BETWEEN 0 AND 10000),headroom_bps integer NOT NULL CHECK(headroom_bps BETWEEN 0 AND 10000),forecast_rps integer NOT NULL,requires_scale boolean NOT NULL,resource_cost_irr bigint NOT NULL DEFAULT 0,captured_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX performance_capacity_service_idx ON performance.capacity_snapshots(tenant_id,service_key,captured_at DESC);
CREATE TABLE performance.scaling_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,service_key text NOT NULL,min_replicas integer NOT NULL CHECK(min_replicas>0),max_replicas integer NOT NULL CHECK(max_replicas>=min_replicas),target_utilization_bps integer NOT NULL CHECK(target_utilization_bps BETWEEN 1000 AND 9000),max_scale_step integer NOT NULL DEFAULT 2,cooldown_seconds integer NOT NULL DEFAULT 300,cost_guardrail_irr bigint NOT NULL,version integer NOT NULL DEFAULT 1,published_at timestamptz,UNIQUE(tenant_id,service_key,version));
CREATE TABLE performance.daily_metrics(tenant_id uuid NOT NULL,metric_date date NOT NULL,active_load_runs integer NOT NULL DEFAULT 0,services_near_limit integer NOT NULL DEFAULT 0,capacity_headroom_bps integer NOT NULL DEFAULT 10000,p95_api_ms integer NOT NULL DEFAULT 0,p95_search_ms integer NOT NULL DEFAULT 0,chat_connections integer NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,metric_date));
CREATE OR REPLACE FUNCTION performance.evidence_append_only()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'performance evidence is append only';END$$;
CREATE TRIGGER performance_budget_results_append_only BEFORE UPDATE OR DELETE ON performance.budget_results FOR EACH ROW EXECUTE FUNCTION performance.evidence_append_only();
ALTER TABLE performance.services ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.budgets ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.load_profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.load_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.budget_results ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.capacity_snapshots ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.scaling_policies ENABLE ROW LEVEL SECURITY;ALTER TABLE performance.daily_metrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_services ON performance.services USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_budgets ON performance.budgets USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_profiles ON performance.load_profiles USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_runs ON performance.load_runs USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_results ON performance.budget_results USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_capacity ON performance.capacity_snapshots USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_scaling ON performance.scaling_policies USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_metrics ON performance.daily_metrics USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);
